import{d as p,C as s,o as g,c as d,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"正易心法·第三十二章","description":"《正易心法》第三十二章——数成于三，重之则六：气之数起于一、偶于二、成于三，重之为六；三为少阳（春）、六为太阳（夏）是进数，三为少阴（秋）、六为太阴（冬）是退数；三画经卦、六画重卦之由。","frontmatter":{"title":"正易心法·第三十二章","description":"《正易心法》第三十二章——数成于三，重之则六：气之数起于一、偶于二、成于三，重之为六；三为少阳（春）、六为太阳（夏）是进数，三为少阴（秋）、六为太阴（冬）是退数；三画经卦、六画重卦之由。","category":"guide","aliases":["正易心法第三十二章","数成于三重之则六","进退之数"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-32.md","filePath":"yijing/zheng-yi-xin-fa/chapter-32.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-32.md"},x=p({...c,setup(u){const i=[{id:"z32-01",label:"一、数成于三",showLabel:!0,sentences:[["数成于三，重之则六。其退亦六，是为乾坤。"]],note:["数在三这里完成，将三重叠则得六；退行的方向也是六——这就是乾坤之数。（**本章回答的是「元问题」**：为什么是六爻？为什么不是四画、五画？**答案：因为气数完备于三，重叠则为六**——**三画经卦、六画重卦，不是人为规定，是自然完备的节点。**）"]},{id:"z32-02",label:"二、起一偶二成三",showLabel:!0,sentences:[["夫气之数，起于一，偶于二，成于三，",{text:"无以加",glossary:"wuyijia"},"矣。重之则为六也。"]],note:["气的数，从一开始，在二处成偶，在三处完成，没有什么可以再加的了；将三重叠，就成为六。（**数的三个阶段**：一＝起点，奇数之始，阳之萌动；二＝成偶，阴阳分化，有了对立；三＝完成，天、地、人三才具备。**为什么三是完成？因为任何结构有了「两端＋中介」就完备了**——天（上）＋地（下）＋人（中），起点＋终点＋过程。）"]},{id:"z32-03",label:"三、乾之进数",showLabel:!0,sentences:[["然三，",{text:"少阳",glossary:"shaoyang"},"也。六，",{text:"太阳",glossary:"taiyang"},"也。三，春也。六，夏也。此乾之数也，是为",{text:"进数",glossary:"jinshu"},"。"]],note:["然而三是少阳，六是太阳；三是春，六是夏。这是乾的数，是进数。（**方向：向前、向上、生长、发散。**「太阳」在此是「阳气之太（极）」，不是今天说的日头；「少阳」是阳气初生。**三爻（经卦）是阳气初成，六爻（重卦）是阳气极盛。**）"]},{id:"z32-04",label:"四、乾坤之退数",showLabel:!0,sentences:[["其退亦六。三，",{text:"少阴",glossary:"shaoyin"},"也。六，",{text:"太阴",glossary:"taiyin"},"也。三，秋也。六，冬也。此乾坤之数也，是为",{text:"退数",glossary:"tuishu"},"。"]],note:["退行方向也是六：三是少阴，六是太阴；三是秋，六是冬。这是乾坤的数，是退数。（**有趣的对称**：三与六各出现两次——「少阳／太阳」一组，「少阴／太阴」一组；「春／夏」一组，「秋／冬」一组。**同一个数字，在进与退两个方向上是同一位置的两种性质：三既是「阳之初」，也是「阴之初」；六既是「阳之极」，也是「阴之极」。**）"]},{id:"z32-05",label:"五、三画与六画",showLabel:!0,sentences:[["三画为经卦，六画为重卦者，凡以此而已。"]],note:["三爻为经卦、六爻为重卦，全都是因为这个道理。（**这是本章的落点**：**不是「圣人规定三爻和六爻」，而是「气数自然完备于三、自然重叠为六」。** 三画六画，是自然之理，非人为设计——与第二十章「本之自然」、第二十八章「不可得而容心」同一立场。）"]}],o=[{id:"wuyijia",term:"无以加",pinyin:"wú yǐ jiā",meaning:"没有什么可以再加的了。三已经是气数的完备状态。"},{id:"shaoyang",term:"少阳",pinyin:"shào yáng",meaning:"阳气的初生阶段（三），对应春天。"},{id:"taiyang",term:"太阳",pinyin:"tài yáng",meaning:"阳气的极盛阶段（六），对应夏天。此处「太阳」指阳气之太，非今日的日头。"},{id:"shaoyin",term:"少阴",pinyin:"shào yīn",meaning:"阴气的初生阶段（三），对应秋天。"},{id:"taiyin",term:"太阴",pinyin:"tài yīn",meaning:"阴气的极盛阶段（六），对应冬天。"},{id:"jinshu",term:"进数",pinyin:"jìn shù",meaning:"向前增长的数。阳气从少到太，从三到六，是进。"},{id:"tuishu",term:"退数",pinyin:"tuì shù",meaning:"向后收缩的数。阴气从少到太，从三到六，是退（阳退）。"}];return(b,n)=>{const r=s("DaoTextReading"),l=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t("",21)),e(r,{colophon:"数成于三 · 起一偶二成三 · 进数退数 · 三画六画",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第三十二章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本，不作统一。原文「此乾坤之数也」承上文「此乾之数也」而言，读者可并观。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"起一偶二成三",pinyin:["qǐ","yī"],meaning:"一＝起点（阳之萌动）；二＝成偶（阴阳分化）；三＝完成（天地人三才，无以加矣）。"},{term:"重之则六",pinyin:["chóng","zhī"],meaning:"将三重叠则得六——三画经卦叠为六画重卦，非人为规定。"},{term:"进数 · 退数",pinyin:["jìn","shù"],meaning:"进数：少阳（春三）→ 太阳（夏六）；退数：少阴（秋三）→ 太阴（冬六）。"},{term:"其退亦六",pinyin:["qí","tuì"],meaning:"退的方向也到六——六不是量，是「完备状态」：阳到六而极，阴到六也极。"},{term:"三画六画",pinyin:["sān","huà"],meaning:"三画为经卦、六画为重卦的理由：气数完备于三，自然重叠为六。"}]}),n[3]||(n[3]=t("",24))])}}});export{m as __pageData,x as default};
